// agent-monitor-hook-plugin v1
// Generated by agent-monitor (am): reports this OpenCode's sessions to the am
// dashboard by running am-hook with a Claude-style JSON payload on stdin.
// `am hooks install --agent opencode` rewrites this file and
// `am hooks uninstall --agent opencode` deletes it. Don't edit it by hand.

import { spawn } from "node:child_process";

// am-hook's argv; the event name goes last. An empty --worktree makes am-hook
// use the payload's cwd. As a shell command:
// __AM_HOOK_COMMAND__
const HOOK = [__AM_HOOK_ARGV__];
const TIMEOUT_MS = 5000;
const MAX_QUEUED = 200;
const MAX_SESSIONS = 200;
// Errors that don't end the turn: an interrupt (the idle that follows ends
// it) and a context overflow (OpenCode compacts and carries on).
const NOT_TERMINAL = new Set(["MessageAbortedError", "ContextOverflowError"]);
// The tool arguments am summarises; nothing else (file contents) is sent.
const INPUT_KEYS = ["command", "description", "file_path", "pattern", "url", "query", "prompt"];

// One hook at a time, in order, so a Stop can't overtake the PostToolUse
// before it. Never awaited by OpenCode.
let chain = Promise.resolve();
let queued = 0;

function runHook(event, payload) {
  return new Promise((resolve) => {
    let settled = false;
    let timer = null;
    const done = () => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      resolve();
    };
    let child;
    try {
      child = spawn(HOOK[0], [...HOOK.slice(1), event], { stdio: ["pipe", "ignore", "ignore"], detached: true });
    } catch (_) {
      return done();
    }
    child.on("error", done);
    child.on("close", done);
    timer = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch (_) {}
      done();
    }, TIMEOUT_MS);
    child.unref();
    try {
      child.stdin.on("error", () => {});
      child.stdin.end(JSON.stringify(payload));
    } catch (_) {}
  });
}

function send(event, payload) {
  if (queued >= MAX_QUEUED) return;
  queued += 1;
  chain = chain
    .then(() => runHook(event, payload))
    .catch(() => {})
    .then(() => { queued -= 1; });
}

function str(v) {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

function toolInput(args) {
  if (!args || typeof args !== "object") return undefined;
  const out = {};
  if (str(args.filePath)) out.file_path = args.filePath;
  for (const k of INPUT_KEYS) if (str(args[k])) out[k] = args[k].slice(0, 500);
  return Object.keys(out).length ? out : undefined;
}

export const AgentMonitor = async ({ directory } = {}) => {
  // Per session: its parent (a subagent's), whether a turn is open (one Stop
  // per turn: OpenCode reports idle twice) and the permission requests
  // waiting on the user.
  const sessions = new Map();

  const state = (id) => {
    let s = sessions.get(id);
    if (!s) {
      s = { parent: null, agentType: null, cwd: null, turn: false, perms: new Set() };
      sessions.set(id, s);
      if (sessions.size > MAX_SESSIONS) sessions.delete(sessions.keys().next().value);
    }
    return s;
  };

  const learn = (info) => {
    const id = info && str(info.id);
    if (!id) return null;
    const s = state(id);
    if (str(info.directory)) s.cwd = info.directory;
    if (str(info.parentID)) {
      s.parent = info.parentID;
      const m = /\(@([\w-]+) subagent\)/.exec(info.title || "");
      s.agentType = str(info.agent) || (m && m[1]) || s.agentType || "subagent";
    }
    return id;
  };

  // A subagent's events are reported from its parent's side.
  const emit = (id, event, extra) => {
    const s = state(id);
    const payload = { session_id: id, cwd: s.cwd || directory || process.cwd(), hook_event_name: event, ...extra };
    if (s.parent) {
      payload.session_id = s.parent;
      payload.agent_id = id;
      payload.agent_type = s.agentType || "subagent";
    }
    send(event, payload);
  };

  const begin = (id) => {
    const s = state(id);
    if (s.turn) return;
    s.turn = true;
    emit(id, s.parent ? "SubagentStart" : "UserPromptSubmit");
  };

  const end = (id, failed) => {
    const s = state(id);
    if (!s.turn) return;
    s.turn = false;
    if (s.perms.size && !s.parent) emit(id, "PostToolUse");
    s.perms.clear();
    emit(id, s.parent ? "SubagentStop" : failed ? "StopFailure" : "Stop");
  };

  const handle = (event) => {
    if (!event || typeof event.type !== "string") return;
    // V1 events carry `properties`, V2 `data`.
    const p = event.properties || event.data || {};
    const type = event.type;
    const id = (type.startsWith("session.") && learn(p.info)) || str(p.sessionID) || str(p.sessionId);
    if (!id) return;
    const s = state(id);
    switch (type) {
      case "session.created":
        if (s.parent) begin(id);
        else emit(id, "SessionStart");
        break;
      case "session.updated":
        if (p.info && p.info.time && p.info.time.archived && !s.parent) {
          emit(id, "SessionEnd");
          sessions.delete(id);
        }
        break;
      case "session.deleted":
        if (s.parent) end(id, false);
        else emit(id, "SessionEnd");
        sessions.delete(id);
        break;
      case "session.status": {
        const st = typeof p.status === "string" ? p.status : p.status && p.status.type;
        if (st === "busy") begin(id);
        else if (st === "idle") end(id, false);
        break;
      }
      case "session.next.prompted":
      case "session.execution.started":
        begin(id);
        break;
      case "session.idle":
      case "session.execution.succeeded":
        end(id, false);
        break;
      case "session.execution.interrupted":
        // OpenCode resumes an execution interrupted by its own shutdown.
        if (p.reason !== "shutdown") end(id, false);
        break;
      case "session.error":
        if (!NOT_TERMINAL.has(p.error && p.error.name)) end(id, true);
        break;
      case "session.execution.failed":
        end(id, true);
        break;
      case "permission.asked":
      case "permission.updated": {
        const req = str(p.id) || str(p.requestID) || "permission";
        s.perms.add(req);
        emit(id, "PermissionRequest", { tool_name: str(p.permission) || str(p.type) || "permission" });
        break;
      }
      case "permission.replied": {
        const req = str(p.requestID) || str(p.permissionID) || "permission";
        if (!s.perms.delete(req) || s.perms.size) break;
        // Back to work: reported on the top-level session, which the
        // permission request had set waiting.
        send("PostToolUse", { session_id: s.parent || id, cwd: s.cwd || directory || process.cwd(), hook_event_name: "PostToolUse" });
        break;
      }
      default:
        break;
    }
  };

  const tool = (event) => (input, output) => {
    try {
      const id = input && str(input.sessionID);
      if (!id) return;
      begin(id);
      const args = (output && output.args) || (input && input.args);
      emit(id, event, { tool_name: str(input.tool) || "unknown", tool_input: toolInput(args) });
    } catch (_) {}
  };

  return {
    event: async ({ event } = {}) => {
      try {
        handle(event && event.event && event.event.type ? event.event : event);
      } catch (_) {}
    },
    "tool.execute.before": tool("PreToolUse"),
    "tool.execute.after": tool("PostToolUse"),
  };
};
